from authoring import *
# Additions to v0.2 chapters only. Existing prose, source photos, question IDs and answers stay intact.
UPDATES={
'learn.recall':('Nach einer Erklärung schliesst du die Vorlage. Wenn du nun drei Kernaussagen selbst hervorholst, übst du Abruf. Das blosse Erkennen derselben Sätze ist ein anderer Vorgang.','Schliesse heute eine Notiz und formuliere drei Gedanken daraus ohne Vorlage.',recall('Wissen ohne sichtbare Vorlage hervorholen nennt man ___.','Abruf|Erinnerungsabruf','Abruf zeigt, was du selbst verfügbar machen kannst.',True),order('Ordne den kurzen Selbsttest.',['Vorlage schliessen','Eigene Kernaussagen notieren','Mit der Erklärung vergleichen'],'Die eigene Antwort muss vor dem Vergleich entstehen.')),
'learn.spacing':('Eine Wiederholung hat zwei Teile: erst erinnern, dann korrigieren. Anschliessend planst du einen späteren Abruf. Der Abstand ist ein Werkzeug und keine feste Gedächtnisgarantie.','Plane zu einem Begriff einen Abruf morgen und einen weiteren einige Tage später.',recall('Wiederholungen über mehrere Zeitpunkte zu verteilen heisst ___.','verteiltes Lernen|verteilte Wiederholung|Spaced Repetition','Der Abstand verlangt erneuten Abruf statt unmittelbares Nachklicken.',True),order('Ordne eine Wiederholungsrunde.',['Ohne Vorlage antworten','Fehler mit Erklärung korrigieren','Einen späteren Abruf planen'],'Rückmeldung und zeitlicher Abstand erfüllen unterschiedliche Aufgaben.')),
'learn.calibration':('Kalibrierung bedeutet, dass Sicherheit und tatsächliche Treffergenauigkeit zusammenpassen. Wenn du bei zehn als sicher markierten Antworten vier Fehler machst, lohnt sich ein genauer Blick auf die falschen sicheren Urteile.','Markiere vor drei Antworten deine Sicherheit und vergleiche sie anschliessend mit dem Ergebnis.',recall('Wie heisst die Abstimmung von gefühlter Sicherheit und tatsächlicher Richtigkeit?','Kalibrierung','Gut kalibriert bedeutet nicht, immer maximal sicher zu sein.'),number('Von zehn als sicher markierten Antworten sind vier falsch. Wie viele waren richtig?',6,'Antworten','10 − 4 = 6 richtige Antworten.')),
'think.implication':('Aus Wenn A, dann B folgt nicht automatisch Wenn B, dann A. Dieser unzulässige Umkehrschluss scheitert, sobald B auch aus einem anderen Grund entstehen kann.','Suche im Alltag eine Wenn-dann-Behauptung und eine alternative Ursache für ihren zweiten Teil.',recall('Der ungeprüfte Schluss von B zurück auf A heisst hier ___.','Umkehrschluss|unzulässiger Umkehrschluss','Andere Wege zu B müssen ausgeschlossen sein.',True),multi('Welche Aussagen folgen aus dem Kapitel?',['Ein Zertifikat kann andere Erwerbswege haben.','Die Regel muss in beide Richtungen gleich gelten.','Ein Gegenbeispiel kann einen zwingenden Rückschluss widerlegen.','Der Rückschluss braucht zusätzliche Voraussetzungen.'],[0,2,3],'Eine Implikation ist keine automatische Gleichwertigkeit.')),
'think.causality':('Ein Drittfaktor kann zwei Beobachtungen gleichzeitig beeinflussen. Für den Freibadfall ist sonniges Wetter eine plausible gemeinsame Erklärung für mehr Eisverkäufe und mehr Sonnenbrand.','Notiere zu einem scheinbaren Zusammenhang eine alternative gemeinsame Ursache.',recall('Eine weitere Grösse, die beide Beobachtungen beeinflusst, heisst hier ___.','Drittfaktor|Drittvariable|gemeinsame Ursache','Sie kann einen Zusammenhang erklären, ohne dass A direkt B verursacht.',True),multi('Welche Erklärungen bleiben für einen beobachteten Zusammenhang grundsätzlich möglich?',['Eine gemeinsame Ursache','Eine direkte Ursache','Zufall','Nur die erste spontane Vermutung'],[0,1,2],'Ein Zusammenhang allein entscheidet nicht zwischen diesen Erklärungen.')),
'think.experiments':('Bevor du einen Lernplan vergleichst, legst du ein Erfolgskriterium fest. Dann gestaltest du den Vergleich und wertest nach dieser Regel aus. Nachträglich nur die schönste Kennzahl herauszusuchen wäre Rosinenpicken.','Lege vor einem kleinen Test genau eine Hauptmessgrösse und den Vergleichszeitpunkt fest.',recall('Das nachträgliche Herausgreifen nur passender Ergebnisse heisst hier ___.','Rosinenpicken|Cherry Picking','Vorab festgelegte Kriterien helfen, diesen Fehler zu begrenzen.',True),order('Ordne einen fairen Test.',['Messkriterium vorher festlegen','Vergleich unter möglichst passenden Bedingungen durchführen','Nach dem vereinbarten Kriterium auswerten'],'Das Kriterium darf nicht erst vom gewünschten Ergebnis abhängen.')),
'data.average':('Für die sortierte Reihe 10, 10, 40 ist der Median 10, der Mittelwert aber 20. Ein einzelner hoher Wert verändert den Mittelwert deutlich, ohne die mittlere Beobachtung zu verschieben.','Berechne Mittelwert und Median von fünf eigenen unkritischen Messwerten.',recall('Der mittlere Wert einer sortierten ungeraden Datenreihe heisst ___.','Median','Der Mittelwert wird dagegen aus Summe und Anzahl berechnet.',True),number('Was ist der Median der Reihe 10, 10, 40?',10,'Einheiten','Der mittlere der drei sortierten Werte ist 10.')),
'data.percent':('Bei 100 CHF Ausgangspreis entsprechen 20 Prozent einer Änderung um 20 CHF. Sinkt ein Anteil von 10 Prozent auf 5 Prozent, ist die absolute Anteilsänderung hingegen 5 Prozentpunkte.','Übersetze eine Prozentmeldung in Ausgangswert und Endwert.',recall('Eine Differenz zwischen zwei Prozentanteilen gibst du in ___ an.','Prozentpunkten|Prozentpunkte','Das ist vom relativen prozentualen Rückgang zu unterscheiden.',True),number('Ein Preis von 100 CHF steigt um 20 Prozent. Neuer Preis?',120,'CHF','100 + 20 = 120 CHF.')),
'data.base-rate':('Die Basisrate ist der Anteil des gesuchten Merkmals in der gesamten betrachteten Gruppe. Im Teilebeispiel sind 10 von 1’000 Teilen defekt, also 1 Prozent. Unter den markierten Teilen gilt ein anderer Nenner.','Schreibe bei einer Trefferquote zuerst den Nenner aus: alle Teile, alle Defekte oder alle markierten Teile?',recall('Der Anteil eines Merkmals in der gesamten Ausgangsgruppe heisst ___.','Basisrate|Grundrate','Seltene Merkmale verlangen besonders sorgfältige Nenner.',True),number('10 wirklich defekte unter 20 markierten Teilen: Anteil defekt unter den markierten?',50,'%','10 / 20 × 100 = 50 Prozent.')),
'digital.phishing':('Bei einer überraschenden Zahlungsanweisung unterbrichst du den Druck, öffnest einen bereits bekannten Kontaktweg und prüfst die Bitte dort. Ein zweiter Kontaktweg aus derselben verdächtigen Nachricht ist keine unabhängige Kontrolle.','Prüfe bei einer unkritischen Beispielnachricht, welchen unabhängigen Kontaktweg du verwenden würdest.',recall('Täuschende Nachrichten zum Abgreifen von Zugangsdaten nennt man häufig ___.','Phishing','Die Prüfung sollte über einen unabhängig bekannten Weg erfolgen.',True),order('Ordne die sichere Reaktion.',['Nicht unter dem Zeitdruck handeln','Bekannten unabhängigen Kontaktweg öffnen','Anliegen dort verifizieren'],'Der unabhängige Weg ist entscheidend.')),
'digital.accounts':('Ein Passwortmanager hilft, unterschiedliche Passwörter zu verwenden. Ein Wiederherstellungscode dient einem geregelten Zugang bei Problemen mit der Anmeldung und muss deshalb besonders geschützt werden.','Prüfe bei einem wichtigen Konto, ob du den geschützten Wiederherstellungsweg kennst.',recall('Ein Werkzeug zum Verwalten unterschiedlicher Passwörter heisst ___.','Passwortmanager|Password Manager','Der Zugang zum Manager verdient besonderen Schutz.',True),multi('Was verbessert die Kontosicherheit im beschriebenen Modell?',['Unterschiedliche Passwörter','Unerwartete Freigabeanfragen bestätigen','Wiederherstellungscodes geschützt verwahren','Zusätzliche passende Anmeldefaktoren'],[0,2,3],'Unerwartete Bestätigungen können gerade einen fremden Anmeldeversuch ermöglichen.')),
'digital.backup':('Eine Synchronisation gleicht Datenstände ab. Eine versionierte Sicherung kann zusätzlich einen früheren Stand bewahren. Erst ein erfolgreicher Wiederherstellungstest zeigt, dass der benötigte Rückweg funktioniert.','Stelle eine unkritische Beispieldatei aus deiner Sicherung wieder her.',recall('Das Prüfen, ob eine Datei wirklich zurückgeholt werden kann, ist ein ___.','Wiederherstellungstest|Restore-Test','Die blosse Existenz einer Kopie beweist den Rückweg nicht.',True),order('Ordne einen kontrollierten Sicherungstest.',['Unkritische Testdatei sichern','Den dokumentierten Wiederherstellungsweg verwenden','Wiederhergestellten Inhalt prüfen'],'Der Test soll keine wichtigen Daten gefährden.')),
'economy.opportunity':('Bei drei Alternativen zählt für Opportunitätskosten die beste aufgegebene verfügbare Option. Nicht alle denkbaren Vorteile werden addiert; die gleiche Stunde lässt sich ohnehin nicht mehrfach gleichzeitig nutzen.','Benenne vor einer freien Stunde die beste Alternative, auf die du mit deiner Wahl verzichtest.',recall('Der Wert der besten aufgegebenen Alternative sind die ___.','Opportunitätskosten|Opportunitaetskosten','Es zählt die beste tatsächlich verfügbare Alternative.',True),multi('Welche Aussagen stimmen?',['Auch kostenlose Angebote beanspruchen Zeit.','Alle denkbaren Alternativen müssen addiert werden.','Die beste verfügbare Alternative ist relevant.','Freizeit muss nicht immer in Geld bewertet werden.'],[0,2,3],'Die Regel macht die Wahl sichtbar, nicht das ganze Leben zu einer Geldrechnung.')),
'economy.sunk':('Versunkene Kosten sind bereits angefallen und nicht mehr rückholbar. Für die nächste Entscheidung zählen veränderbare zukünftige Folgen. Ein noch erzielbarer Verkaufserlös ist gerade nicht versunken.','Prüfe eine Fortsetzungsentscheidung mit der Frage: Was ändert sich wirklich ab jetzt?',recall('Bereits angefallene nicht rückholbare Ausgaben heissen ___.','versunkene Kosten|Sunk Costs','Künftige Gebühren und noch erzielbare Erlöse sind getrennt zu betrachten.',True),multi('Welche Grössen gehören in eine Entscheidung ab jetzt?',['Noch erzielbarer Verkaufserlös','Künftige Kündigungsgebühr','Unwiderruflich verlorener Kaufpreis als rückholbarer Nutzen','Künftige Auswirkungen auf andere'],[0,1,3],'Nicht veränderbare Vergangenheit und veränderbare Zukunft sind zu trennen.')),
'economy.margin':('Der zusätzliche Beitrag ergibt sich aus zusätzlichem Erlös minus zusätzlichen Kosten. Bringt die nächste Runde 30 CHF und kostet 20 CHF, bleiben 10 CHF. Das beantwortet noch nicht die gesamte Rentabilität des Betriebs.','Untersuche eine nächste zusätzliche Aufgabe nach zusätzlichem Nutzen und zusätzlichem Aufwand.',recall('Die Betrachtung der nächsten zusätzlichen Einheit nennt man ___.','marginal|Marginalbetrachtung','Sie unterscheidet sich von der Betrachtung des gesamten Betriebs.',True),number('30 CHF zusätzlicher Erlös minus 20 CHF zusätzliche Kosten: Beitrag?',10,'CHF','30 − 20 = 10 CHF.')),
'science.energy':('Eine Energiebilanz nennt den betrachteten Systemrand. Im vereinfachten Beispiel werden 100 Energieeinheiten zu 60 Einheiten gewünschter Wirkung und 40 Einheiten Wärme. Die Wärme ist weiterhin Energie, aber nicht dieselbe Nutzform.','Benenne bei einem Energieumwandlungsprozess Eingang, gewünschte Wirkung und weitere Energieformen.',recall('Die Grenze des betrachteten Systems nennen wir ___.','Systemgrenze|Systemrand','Ohne klare Grenze bleibt die Bilanz unbestimmt.',True),number('100 Energieeinheiten gehen hinein, 60 dienen der gewünschten Wirkung. Wie viele bleiben für andere Formen?',40,'Einheiten','100 − 60 = 40; Energie wird nicht einfach vernichtet.')),
'science.power':('Für konstante Leistung gilt Energie gleich Leistung mal Zeit. 100 Watt während zwei Stunden ergeben 200 Wattstunden. Die Einheiten verraten die Rechenoperation.','Lies die Leistungsangabe eines Geräts und rechne mit einer angenommenen Laufzeit.',recall('Welche Einheit ist Energie: Watt oder Wattstunde?','Wattstunde|Wh','Watt ist Leistung, Wattstunde eine Energiemenge.'),number('100 Watt konstant während 2 Stunden: Energie?',200,'Wh','100 W × 2 h = 200 Wh.')),
'science.scale':('Um km/h in m/s umzuwandeln, teilst du durch 3.6: Ein Kilometer sind 1’000 Meter, eine Stunde 3’600 Sekunden. Daher entsprechen 36 km/h genau 10 m/s.','Prüfe eine Alltagszahl zuerst durch Einheiten und grobe Überschlagsrechnung.',recall('Eine grobe Rechnung zur Plausibilitätsprüfung nennt man ___.','Überschlagsrechnung|Ueberschlagsrechnung|Überschlag','Sie ersetzt nicht jede genaue Rechnung, entdeckt aber Grössenfehler.',True),number('Wie viele Meter pro Sekunde entsprechen 36 km/h?',10,'m/s','36 / 3.6 = 10.')),
'earth.weather':('Die Aussage Heute regnet es beschreibt Wetter. Eine langfristige Verteilung von Temperaturen beschreibt Klima. Beide Aussagen können richtig sein, weil sie verschiedene Zeitskalen betreffen.','Trenne in einem Wetterbericht Tageszustand und Aussagen über langfristige Entwicklung.',recall('Der atmosphärische Zustand an einem Ort zu einem konkreten Zeitpunkt ist das ___.','Wetter','Klima beschreibt langfristige Verteilungen und Schwankungen.',True),multi('Was braucht eine belastbare Aussage über einen Klimatrend?',['Vergleichbare Beobachtungen über viele Jahre','Nur einen besonders kalten Nachmittag','Berücksichtigung von Schwankungen','Eine passende zeitliche Einordnung'],[0,2,3],'Ein einzelner Tag reicht für den langfristigen Trend nicht aus.')),
'earth.greenhouse':('Die Erde gibt Energie als Infrarotstrahlung ab. Treibhausgase absorbieren einen Teil und emittieren selbst. Absorption und Emission bezeichnen verschiedene Schritte im Strahlungsaustausch.','Erkläre den Treibhauseffekt ohne die Wörter Ozonloch oder Loch in der Atmosphäre zu verwenden.',recall('Die Erde gibt einen wesentlichen Teil ihrer Energie als ___ ab.','Infrarotstrahlung|Wärmestrahlung|Waermestrahlung','Treibhausgase beeinflussen den Austausch dieser Strahlung.',True),multi('Welche Aussagen passen?',['Treibhausgase absorbieren einen Teil der Infrarotstrahlung.','Treibhausgase emittieren selbst Strahlung.','Ozonloch und Treibhauseffekt sind identisch.','Die Energiebilanz ist für die Temperaturentwicklung relevant.'],[0,1,3],'Die beteiligten atmosphärischen Vorgänge sind zu unterscheiden.')),
'earth.water':('Kondensation ist der Übergang von Wasserdampf zu flüssigem Wasser. Verdunstung beschreibt die Gegenrichtung. Niederschlag bringt Wasser aus der Atmosphäre zurück zur Oberfläche, etwa als Regen oder Schnee.','Beobachte beschlagendes Glas und benenne den Phasenübergang.',recall('Der Übergang von Wasserdampf zu flüssigem Wasser heisst ___.','Kondensation','Verdunstung beschreibt die umgekehrte Richtung.',True),order('Ordne einen vereinfachten Weg im Wasserkreislauf.',['Wasser verdunstet','Wasserdampf kondensiert','Wasser fällt als Niederschlag'],'Nicht jeder Tropfen nimmt denselben Weg oder braucht gleich lange.')),
'history.sources':('Für die Frage nach dem Alltag einer Epoche kann ein damaliges Tagebuch eine Primärquelle sein. Ein späteres Werk interpretiert solche Quellen. Die Einordnung hängt von der Forschungsfrage ab.','Prüfe bei einer historischen Aussage Urheber, Zeitpunkt, Anlass und angesprochenes Publikum.',recall('Eine unmittelbare Quelle zur untersuchten historischen Frage heisst häufig ___.','Primärquelle|Primaerquelle','Auch Primärquellen müssen kritisch eingeordnet werden.',True),multi('Was gehört zur Quellenkritik?',['Urheber und Zeitpunkt','Anlass und Publikum','Augenzeugen immer automatisch glauben','Was die Quelle tatsächlich belegt'],[0,1,3],'Nähe zum Ereignis bedeutet keine garantierte Unfehlbarkeit.')),
'history.timeline':('Apollo 8 umrundete den Mond 1968; Apollo 11 landete 1969 erstmals bemannt auf dem Mond. Apollo 17 startete 1972. Eine Chronologie ordnet Ereignisse zeitlich und ist noch keine vollständige Ursachenerklärung.','Ordne drei bekannte Ereignisse zeitlich und ergänze eine Frage nach einem tatsächlichen Wirkungszusammenhang.',recall('Eine zeitliche Ordnung von Ereignissen heisst ___.','Chronologie','Chronologie und Kausalerklärung sind verschiedene Aufgaben.',True),order('Ordne die Missionen zeitlich.',['Apollo 8 · 1968','Apollo 11 · 1969','Apollo 17 · 1972'],'Die Reihenfolge ergibt sich aus den dokumentierten Jahreszahlen.')),
'history.photos':('Sichtbar ist, was im Bild erkennbar dargestellt wird. Die Rezeption beschreibt, wie Menschen ein Bild aufnehmen und deuten. Ein Foto zeigt seine gesellschaftliche Wirkung nicht automatisch selbst.','Trenne bei einem Foto drei sichtbare Merkmale von einer Behauptung über seine Wirkung.',recall('Wie Menschen ein Bild aufnehmen und deuten, nennt man seine ___.','Rezeption','Die Wirkung braucht zusätzliche Belege über die Aufnahme durch Menschen.',True),multi('Welche Aussagen sind beim beschriebenen Erdfoto unmittelbar visuell prüfbar?',['Es sind Wolken sichtbar.','Es gibt einen dunklen Hintergrund.','Alle Menschen wurden sofort vereint.','Landflächen sind erkennbar.'],[0,1,3],'Eine globale gesellschaftliche Wirkung ist keine sichtbare Eigenschaft des Bildes.'))
}
